-- Townlong Steppes: creature abilities
-- No reference scripts the zone's creatures (the yaungol, the mantid, the Sha and the steppes' wildlife), and most had no AI: they
-- cast their sniffed spells (creature_template spell1-8).

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '60647,60683,60689,60690,60692,60713,60725,60726,60756,60763,60841,60951,61019,61153,61376,61540,61619,61635,61661,61811,61960,61971,62266,62307,62441,62530,62577,62580,62589,62613,62677,62789,63684,63685,63686,63688,63888,64802,66162,66188,66194,66289,66309,66310,66319,66471,66593';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
